const b = $json.body || {};
const requeridos = ['url', 'afirmacion'];
const faltan = requeridos.filter(function (campo) {
  const v = b[campo];
  return v === undefined || v === null || String(v).trim() === '';
});
const url = String(b.url || '').trim();
const urlValida = url.indexOf('http://') === 0 || url.indexOf('https://') === 0;
if (!urlValida && url !== '') {
  faltan.push('url (debe empezar por http:// o https://)');
}
const salida = {
  url: url,
  afirmacion: String(b.afirmacion || '').trim().slice(0, 1000),
  faltan: faltan,
  valido: faltan.length === 0 && urlValida
};
return { json: salida };

const origen = $('Validar fuente').item.json;
const pagina = String($json.pagina || '');
const dominio = origen.url.split('/')[2] || '';
const extracto = pagina
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 6000);
const sistema = [
  'Evalúas la credibilidad de una fuente web respecto a una afirmación concreta.',
  'Ten en cuenta: tipo de dominio, tono, presencia de autor y fechas, si el texto respalda o no la afirmación.',
  'Sé escéptico: si el extracto no basta para confirmar, dilo. No inventes.',
  'Responde SOLO con JSON válido:',
  '{ "nivel": "alta|media|baja", "puntuacion": 0, "respalda_afirmacion": "si|no|parcial", "razones": ["..."], "banderas_rojas": ["..."] }'
].join('\n');
const peticion_ia = {
  model: 'claude-opus-5',
  max_tokens: 1024,
  system: sistema,
  messages: [
    { role: 'user', content: 'URL: ' + origen.url + '\nDominio: ' + dominio + '\nHTTPS: ' + (origen.url.indexOf('https://') === 0 ? 'sí' : 'no') + '\n\nAFIRMACIÓN A CONTRASTAR:\n' + origen.afirmacion + '\n\nEXTRACTO DE LA PÁGINA:\n' + extracto }
  ]
};
return { json: { dominio: dominio, longitud_extracto: extracto.length, peticion_ia: peticion_ia } };

const bloques = $json.content || [];
const texto = bloques
  .filter(function (b) { return b.type === 'text'; })
  .map(function (b) { return b.text; })
  .join('\n');
let resultado;
try {
  const inicio = texto.indexOf('{');
  const fin = texto.lastIndexOf('}');
  resultado = JSON.parse(texto.slice(inicio, fin + 1));
} catch (e) {
  resultado = { nivel: 'baja', puntuacion: 0, respalda_afirmacion: 'no', razones: ['respuesta_no_json'], banderas_rojas: [] };
}
const origen = $('Validar fuente').item.json;
const salida = {
  url: origen.url,
  dominio: $('Analizar señales y preparar IA').item.json.dominio,
  afirmacion: origen.afirmacion,
  nivel: resultado.nivel,
  puntuacion: resultado.puntuacion,
  respalda_afirmacion: resultado.respalda_afirmacion,
  razones: (resultado.razones || []).join(' | '),
  banderas_rojas: (resultado.banderas_rojas || []).join(' | ') || 'ninguna',
  verificado_en: new Date().toISOString()
};
return { json: salida };
